pub fn clean(work: &[(&str, &str)], head: &[(&str, &str)]) -> bool {
    work.iter()
        .copied()
        .collect::<std::collections::BTreeMap<_, _>>()
        == head
            .iter()
            .copied()
            .collect::<std::collections::BTreeMap<_, _>>()
}

fn main() {
    assert_eq!(
        clean(&[("b", "2"), ("a", "1")], &[("a", "1"), ("b", "2")]),
        true,
        "case 1"
    );
    assert_eq!(clean(&[], &[]), true, "case 2");
    assert_eq!(
        clean(&[("a", "new")], &[("a", "old")]),
        false,
        "case 3"
    );
    assert_eq!(clean(&[("extra", "x")], &[]), false, "case 4");
    assert_eq!(clean(&[], &[("gone", "x")]), false, "case 5");
    println!("worked example passed");
}

